 14→async function updatePdfContentMassive(req, res) {
 15→    try {
 16→        const company = await getCompany(req.body.company_id);
 17→        if (!company) {
 18→            return res.status(400).send({ status: false, message: "API KEY incorrecta" });
 19→        }
 20→
 21→        const companyPackages = await getCompanyPackages(company.company_id);
 22→        if (!companyPackages) {
 23→            return res.status(400).send({ status: false, message: "No tiene paquetes asignados" });
 24→        }
 25→
 26→        const storage = await service.getStorageUsed(company.company_id);
 27→        if (isStorageExceeded(company, storage)) {
 28→            return res.status(400).send({ status: false, message: "Se ha superado la capacidad de almacenamiento. Por favor, actualice su plan." });
 29→        }
 30→
 31→        const signers_count = req.body.data.length;
 32→
 33→        await processMassivePdfModification(req, res, company, signers_count);
 34→
 35→    } catch (error) {
 36→        console.error('Error updating PDF:', error);
 37→
 38→        if (!res.headersSent) {
 39→            res.status(500).json({ status: false, message: 'Error updating PDF' });
 40→        }
 41→    }
 42→}
