 44→async function processMassivePdfModification(req, res, company, signers_count) {
 45→    const arrData = req.body.data;
 46→    const fields = req.body.fields;
 47→
 48→    const details = await db.document_packages_details.findMany({
 49→        where: {
 50→            document_package_header_id: parseInt(req.body.documentHeaderId),
 51→            active: "1",
 52→        },
 53→        select: {
 54→            id: true,
 55→            name: true,
 56→            content: true,
 57→        },
 58→    });
 59→
 60→    if (!details || details.length === 0) {
 61→        return res.status(400).json({ status: false, message: 'No se encontraron documentos PDF' });
 62→    }
 63→
 64→    const pdfBuffers = {};
 65→    for (const detail of details) {
 66→        const buffer = await axios.get(detail.content, {
 67→            responseType: 'arraybuffer'
 68→        }).then(response => Buffer.from(response.data));
 69→        pdfBuffers[detail.id] = buffer;
 70→    }
 71→
 72→    const documentPackageHeader = await db.document_packages_header.findFirst({
 73→        where: {
 74→            id: parseInt(req.body.documentHeaderId),
 75→        },
 76→        select: {
 77→            name: true,
 78→            order: true,
 79→            group_signers: {
 80→                select: {
 81→                    user_id: true,
 82→                    order: true,
 83→                    user: {
 84→                        select: {
 85→                            id: true,
 86→                            email: true,
 87→                            firstname: true,
 88→                            lastname: true,
 89→                            id_number: true,
 90→                            id_type: true,
 91→                        }
 92→                    }
 93→                },
 94→            }
 95→        }
 96→    });
 97→
 98→    res.setHeader('Content-Type', 'text/event-stream');
 99→    res.setHeader('Cache-Control', 'no-cache');
100→    res.setHeader('Connection', 'keep-alive');
101→    res.setHeader('X-Accel-Buffering', 'no');
102→    res.flushHeaders();
103→
104→    const sendEvent = (eventName, data) => {
105→        res.write(`event: ${eventName}\ndata: ${JSON.stringify(data)}\n\n`);
106→    };
107→
108→    const total = arrData.length;
109→    let processed = 0;
110→    let failed = 0;
111→    const BATCH_SIZE = 5;
112→
113→    sendEvent('progress', { processed: 0, total, failed: 0 });
114→
115→    try {
116→        async function processOneRecord(obj) {
117→            let signer_fields = obj.signers;
118→
119→            const predefinedSigners = documentPackageHeader.group_signers.map(signer => ({
120→                signer_order: signer.order,
121→                user_id: signer.user.id,
122→                nombres: signer.user.firstname,
123→                apellidos: signer.user.lastname,
124→                correo: signer.user.email,
125→                documento: signer.user.id_number,
126→                tipo_documento: signer.user.id_type,
127→            }));
128→
129→            signer_fields = [
130→                ...signer_fields,
131→                ...predefinedSigners.filter(predefSigner =>
132→                    !signer_fields.some(signer => signer.user_id === predefSigner.user_id)
133→                )
134→            ];
135→
136→            const variableValues = obj.variableValues || {};
137→
138→            const s3Keys = [];
139→            for (const detail of details) {
140→                const detailFields = fields.filter(f => {
141→                    if (f.pdfId === undefined || f.pdfId === null) return true;
142→                    return parseInt(f.pdfId) === parseInt(detail.id);
143→                });
144→
145→                const pdfDoc = await PDFDocument.load(pdfBuffers[detail.id]);
146→                const modifiedPdf = await modifyPdfWithFields(pdfDoc, detailFields, signer_fields, variableValues);
147→                const s3Key = await uploadToS3(modifiedPdf, company.id);
148→                s3Keys.push({ detailId: detail.id, s3Key, name: detail.name });
149→            }
150→
151→            await db.$transaction(async (prisma) => {
152→                const users = await getUsers(prisma, signer_fields, company.id);
153→
154→                const documentPackageSigner = await createDocumentPackageSigner(
155→                    prisma,
156→                    obj,
157→                    req.body.user_id_creator,
158→                    company.id,
159→                    users[0].id,
160→                    req.body.documentHeaderId,
161→                    req.body.recipients,
162→                    req.body.sendReminder,
163→                    req.body.reminder_days_interval
164→                );
165→
166→                await prisma.document_packages_signers_logs.create({
167→                    data: {
168→                        document_package_signer_id: parseInt(documentPackageSigner.id),
169→                        event_description: "Solicitud de firma enviada",
170→                        ip_address: req.ip ? req.ip : null,
171→                        performed_by_user_id: parseInt(req.body.user_id_creator),
172→                        created_at: new Date(),
173→                    },
174→                });
175→
176→                for (const { s3Key, detailId, name } of s3Keys) {
177→                    await prisma.document_packages_signers_details_values.create({
178→                        data: {
179→                            document_package_detail_id: detailId,
180→                            document_package_signer_id: parseInt(documentPackageSigner.id),
181→                            name: name,
182→                            company_id: parseInt(documentPackageSigner.company_id),
183→                            visibility: 1,
184→                            document_type_id: 1,
185→                            fields: JSON.stringify(fields),
186→                            signers_fields: JSON.stringify(signer_fields),
187→                            modified_content: s3Key,
188→                            s3_key: s3Key,
189→                            created_at: new Date(),
190→                            updated_at: new Date()
191→                        }
192→                    });
193→                }
194→
195→                await sendSignRequests(res, documentPackageSigner, users, company, signer_fields, req.body.name, documentPackageHeader, prisma);
196→            }, {
197→                maxWait: 100000,
198→                timeout: 100000,
199→            });
200→        }
201→
202→        for (let i = 0; i < total; i += BATCH_SIZE) {
203→            const batch = arrData.slice(i, i + BATCH_SIZE);
204→            const results = await Promise.allSettled(
205→                batch.map(obj => processOneRecord(obj))
206→            );
207→
208→            results.forEach(result => {
209→                if (result.status === 'fulfilled') {
210→                    processed++;
211→                } else {
212→                    failed++;
213→                    console.error('Error processing record:', result.reason);
214→                }
215→            });
216→
217→            sendEvent('progress', { processed, total, failed });
218→        }
219→
220→        sendEvent('complete', {
221→            status: true,
222→            count: processed,
223→            failed,
224→            total,
225→            message: "Solicitud enviada exitosamente"
226→        });
227→
228→        res.end();
229→
230→    } catch (error) {
231→        console.error('Error processing massive PDF modification:', error);
232→        sendEvent('error', { message: 'Error en la modificación masiva del PDF' });
233→        res.end();
234→    }
235→}
