237→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
238→    const pdfDoc = pdfBuffer;
239→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
240→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
241→    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
242→    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
243→    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
244→    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
245→    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
246→    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);
247→
248→    const signatureFields = fields.filter(f => f.type !== 'variable');
249→    const variableFieldsList = fields.filter(f => f.type === 'variable');
250→
251→    await Promise.all(signatureFields.map(async (field) => {
252→        const { pageNumber, top, left, width, height, name } = field;
253→        const page = pdfDoc.getPage(pageNumber - 1);
254→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
255→        const textHeight = helveticaFont.heightAtSize(12);
256→
257→        const x = left + (width / 2) - (textWidth / 2) - 15;
258→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
259→
260→        page.drawText(name, {
261→            x: x,
262→            y: y + 8,
263→            size: 12,
264→            font: helveticaFont
265→        });
266→
267→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
268→
269→        if (signer) {
270→            const fullName = `${signer.nombres} ${signer.apellidos}`;
271→            const docType = await getDocumentTypeName(signer.tipo_documento);
272→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
273→
274→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
275→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
276→
277→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
278→
279→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
280→
281→            page.drawText(fullName, {
282→                x: xFullName,
283→                y: y - textHeight - 8,
284→                size: 10,
285→                font: timesRomanFont
286→            });
287→
288→            page.drawText(docTypeAndNumber, {
289→                x: xDocTypeAndNumber,
290→                y: y - textHeight - 22,
291→                size: 10,
292→                font: timesRomanFont
293→            });
294→        }
295→    }));
296→
297→    for (const field of variableFieldsList) {
298→        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
299→        const page = pdfDoc.getPage(pageNumber - 1);
300→
301→        const varName = name.replace(/\[\$|\]/g, '');
302→        const value = variableValues[varName] || '';
303→
304→        if (!value) continue;
305→
306→        const isBold = fontWeight && parseInt(fontWeight) >= 600;
307→        const isItalic = fontStyle === 'italic';
308→        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');
309→
310→        let selectedFont;
311→        if (isSerif) {
312→            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
313→            else if (isBold) selectedFont = timesRomanBoldFont;
314→            else if (isItalic) selectedFont = timesRomanItalicFont;
315→            else selectedFont = timesRomanFont;
316→        } else {
317→            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
318→            else if (isBold) selectedFont = helveticaBoldFont;
319→            else if (isItalic) selectedFont = helveticaObliqueFont;
320→            else selectedFont = helveticaFont;
321→        }
322→
323→        const maxFontSize = Math.min(height * 0.6, 32);
324→        let fontSize = Math.max(8, maxFontSize);
325→
326→        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
327→        while (textWidth > width - 4 && fontSize > 6) {
328→            fontSize -= 0.5;
329→            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
330→        }
331→
332→        const textHeight = selectedFont.heightAtSize(fontSize);
333→
334→        const x = left + (width / 2) - (textWidth / 2);
335→        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);
336→
337→        let color = rgb(0.39, 0.39, 0.38);
338→        if (fontColor && fontColor.startsWith('#')) {
339→            const hex = fontColor.replace('#', '');
340→            const r = parseInt(hex.substring(0, 2), 16) / 255;
341→            const g = parseInt(hex.substring(2, 4), 16) / 255;
342→            const b = parseInt(hex.substring(4, 6), 16) / 255;
343→            color = rgb(r, g, b);
344→        }
345→
346→        page.drawText(value, {
347→            x: x,
348→            y: y,
349→            size: fontSize,
350→            font: selectedFont,
351→            color: color,
352→        });
353→    }
354→
355→    return await pdfDoc.save();
356→}
