370→async function uploadToS3(pdfBuffer, companyId) {
371→
372→    const uniqueId = crypto.randomBytes(16).toString("hex");
373→
374→    const key = `stored_files/${companyId}/${uniqueId}`;
375→    const uploadParams = {
376→        Bucket: process.env.S3_BUCKET,
377→        Key: key,
378→        Body: pdfBuffer,
379→        ContentType: 'application/pdf',
380→    };
381→
382→    await s3Client.send(new PutObjectCommand(uploadParams));
383→    return key; 
384→}
