444→async function createDocumentPackageSigner(prisma, req, creator, companyId, userId, documentHeaderId, recipients, send_reminder, reminder_days_interval) {
445→    const fingerprint = await generateFingerPrint();
446→
447→    const expires_date = new Date(req.expires_in_days);
448→    formatted_expires_date = expires_date.toISOString();
449→    
450→    const current_date = new Date();
451→    const formatted_current_date = current_date.toISOString();
452→
453→    const request = await prisma.document_packages_signers.create({
454→        data: {
455→            document_package_header_id: parseInt(documentHeaderId),
456→            user_id: parseInt(userId),
457→            company_id: parseInt(companyId),
458→            status: "send",
459→            token: "",
460→            is_pdf: 1,
461→            sent_sign_request_at: formatted_current_date,
462→            fingerprint: fingerprint.replace(":", ""),
463→            ip_address: req.ip,
464→            from_api: 1,
465→            user_id_creator: parseInt(creator),
466→            active: "1",
467→            reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
468→            send_reminder: send_reminder == 1 ? true : false,
469→            expires_in_days: formatted_expires_date,
470→            created_at: new Date(),
471→            updated_at: new Date()
472→        }
473→    });
474→
475→    if (recipients.length > 0) {
476→        const validRecipients = recipients.filter(recipient => recipient.email && recipient.email.trim() !== '');
477→
478→        if (validRecipients.length > 0) {
479→            for (let i = 0; i < validRecipients.length; i++) {
480→                const recipient = validRecipients[i];
481→    
482→                await prisma.request_recipients.create({
483→                    data: {
484→                        document_package_signer_id: request.id,
485→                        type: 1,
486→                        email: recipient.email,
487→                        created_at: new Date(),
488→                        updated_at: new Date(),
489→                    },
490→                });
491→    
492→                await prisma.document_packages_signers_logs.create({
493→                    data: {
494→                        document_package_signer_id: request.id,
495→                        event_description: `Destinatario agregado: ${recipient.email}`,
496→                        ip_address: req.ip ? req.ip : null,
497→                        performed_by_user_id: parseInt(creator),
498→                        created_at: new Date(),
499→                    },
500→                });
501→            }
502→        } else {
503→            console.log("No hay destinatarios válidos");
504→        }
505→    }
506→
507→    return request;
508→}
