511→async function sendSignRequests(res, documentPackageSigner, users, company, signerFields, packageName, documentPackageHeader, prisma) {
512→    const requests = [];
513→    let requestSending = false;
514→
515→    try {
516→        for (const user of users) {
517→            const token = service.createCustomToken({
518→                id: user.id,
519→                document_package_signer_id: documentPackageSigner.id,
520→            });
521→
522→            const fingerprint = await generateFingerPrint();
523→
524→            const signerField = signerFields.find(field => field.correo.toLowerCase().trim() == user.email.toLowerCase().trim());
525→
526→            if (!signerField) {
527→                console.error(`No se encontró signerField para el usuario con correo: ${user.email}`);
528→                continue;  
529→            }
530→
531→            const orderMatch = signerField.signer_order;
532→            const order = orderMatch ? parseInt(orderMatch) : users.indexOf(user) + 1;
533→
534→            await prisma.document_signers.create({
535→                data: {
536→                    document_package_signer_id: documentPackageSigner.id,
537→                    user_id: parseInt(user.id),
538→                    order: order, 
539→                    status: "send",
540→                    token: token,
541→                    sent_sign_request_at: new Date(),
542→                    fingerprint: fingerprint.replace(":", ""),
543→                    expires_in_days: documentPackageSigner.expires_in_days,
544→                    created_at: new Date(),
545→                    updated_at: new Date()
546→                },
547→            });
548→
549→            const url = `${process.env.ENV_URL}${token}`;
550→
551→            if (documentPackageHeader.order == 1 && parseInt(order) === 1) {
552→                requests.push({
553→                    email: user.email,
554→                    company: company,
555→                    firstname: user.firstname,
556→                    lastname: user.lastname,
557→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
558→                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
559→                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
560→                    _url: url,
561→                    company_email: company.email,
562→                    sendRequest: true
563→                });
564→            }
565→
566→            if (documentPackageHeader.order === 2) {
567→                requests.push({
568→                    id: user.id,
569→                    document_package_signer_id: documentPackageSigner.id,
570→                    email: user.email,
571→                    company: company,
572→                    firstname: user.firstname,
573→                    lastname: user.lastname,
574→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
575→                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
576→                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
577→                    _url: url,
578→                    company_email: company.email,
579→                    sendRequest: true
580→                });
581→            }
582→        }
583→
584→        requestSending = true;
585→
586→    } catch (error) {
587→        console.error("Error al generar las solicitudes de firma:", error);
588→    }
589→
590→
591→    await Promise.all(requests.map(async (user) => {
592→        if (requestSending) {
593→
594→            if (user.sendRequest) {
595→                await service.sendSolicitudFirma(
596→                    user.email,
597→                    user.company.avatar,
598→                    `${user.firstname} ${user.lastname}`,
599→                    user.company.fiscal_name,
600→                    user.company.fiscal_name,
601→                    user.passwordGenerated,
602→                    user.date,
603→                    user.time,
604→                    user._url,
605→                    user.company_email,
606→                    packageName,
607→                    user.company.advanced_settings[0].email_message || "",
608→                    user.id,
609→                    user.document_package_signer_id,
610→                    user.company.id
611→                );
612→            }
613→        }
614→    }));
615→   
616→}
