618→async function getCompany(companyId) {
619→    const branch = await db.companies.findFirst({
620→        where: { id: companyId },
621→        select: {
622→            id: true,
623→            company_parent_id: true,
624→            avatar: true,
625→            company_name: true,
626→        }
627→    });
628→
629→    if (!branch) return null;
630→
631→    const parentCompanyId = branch.company_parent_id;
