279→async function createDocumentPackageDetails(res, prisma, details, documentPackageSigner, company, users, header) {
280→    const documentPackageUsers = [];
281→
282→    for (const detail of details) {
283→        for (const key in detail.signers_fields) {
284→            if (detail.signers_fields.hasOwnProperty(key)) {
285→                const signer = detail.signers_fields[key];
286→
287→                const correspondingUser = users.find(user => 
288→                    user.email.trim().toLowerCase() === signer.correo.trim().toLowerCase()
289→                );
290→                if (correspondingUser) {
291→                    documentPackageUsers.push({ user: correspondingUser, order: key });
292→                }
293→            }
294→        }
295→    }
296→
297→    const fieldKeyMap = {};
298→    details.forEach((detail) => {
299→        const fields = detail.fields;
300→
301→        for (const key in fields) {
302→            const fieldKey = key;
303→            const value = fields[key];
304→
305→            if (!fieldKeyMap[fieldKey]) {
306→                fieldKeyMap[fieldKey] = {
307→                    field_key: fieldKey,
308→                    value: null,
309→                    id_detalle_grupo_documento: []
310→                };
311→            }
312→
313→            fieldKeyMap[fieldKey].value = value;
314→        }
315→    });
316→
317→    const packageDetails = await prisma.document_packages_details.findMany({
318→        where: { document_package_header_id: header.id, active: "1" },
319→        select: {
320→            id: true,
321→            fields: true,
322→            template: {
323→                select: {
324→                    tpl_name: true,
325→                    visibility: true,
326→                    document_type_id: true,
327→                    content: true,
328→                 
329→                }
330→            }
331→        }
332→    });
333→
334→    for (const packageDetail of packageDetails) {
335→        let updatedContent = packageDetail.template.content;
336→
337→        const fields = packageDetail.fields.split("|").map(field => field.trim());
338→
339→        fields.forEach((field) => {
340→            if (fieldKeyMap[field]) {
341→                const regex = new RegExp(`{\\s*${field}\\s*}`, "g");
342→                updatedContent = updatedContent.replace(regex, fieldKeyMap[field].value);
343→            }
344→        });
345→
346→        for (const { user, order } of documentPackageUsers) {
347→            const modifiedContent = createModifiedContent(user);
348→            const update_order = order.replace('FIRMA', '');
349→            updatedContent = replaceSignature(updatedContent, update_order, modifiedContent);
350→        }
351→
352→        const detailValue = await prisma.document_packages_signers_details_values.create({
353→            data: {
354→                document_package_detail_id: packageDetail.id,
355→                document_package_signer_id: parseInt(documentPackageSigner.id),
356→                name: packageDetail.template.tpl_name,
357→                company_id: documentPackageSigner.company_id,
358→                visibility: packageDetail.template.visibility,
359→                document_type_id: packageDetail.template.document_type_id,
360→                fields: fields.join("|"),
361→                fields_values: fields.map(field => fieldKeyMap[field]?.value || "").join("|"),
362→                signers_fields: JSON.stringify(details[0].signers_fields),  
363→                modified_content: updatedContent,
364→              
365→                created_at: new Date(),
366→                updated_at: new Date()
367→            }
368→        });
369→
370→        await updateContent(detailValue.id, fields.join("|"), fields.map(field => fieldKeyMap[field]?.value || "").join("|"), prisma);
371→        await generateDocuments(documentPackageSigner, company.id, prisma);
372→    }
373→
374→    await sendSignRequests(res, documentPackageSigner, header, documentPackageUsers, company, prisma);
375→}
