377→async function updateContent(
378→    document_package_signer_detail_value_id,
379→    fields,
380→    fields_values,
381→    prisma
382→) {
383→    let tmpFields = fields.split("|");
384→
385→    let tmpFieldsValues = fields_values.split("|");
386→
387→    let documentPackageDetail = await prisma.document_packages_signers_details_values.findFirst({
388→        where: {
389→            id: document_package_signer_detail_value_id,
390→        },
391→        select: {
392→           modified_content: true,
393→        }
394→    });
395→
396→    try {
397→        if (documentPackageDetail) {
398→            let content = documentPackageDetail.modified_content;
399→
400→            for (let i = 0; i < tmpFields.length; i++) {
401→
402→                let valueToReplace = i < tmpFieldsValues.length && tmpFieldsValues[i] != null ? tmpFieldsValues[i] : "";
403→                let fieldRegex = new RegExp("{\\s*" + tmpFields[i] + "\\s*}", "g");
404→
405→
406→                content = content.replace(fieldRegex, valueToReplace);
407→            }
408→
409→
410→            let allFieldsInContent = [...content.matchAll(/{\s*([\w\d_]+)\s*}/g)];
411→
412→            for (let match of allFieldsInContent) {
413→                let field = match[1]; 
414→                if (!tmpFields.includes(field)) {
415→                    let orphanFieldRegex = new RegExp("{\\s*" + field + "\\s*}", "g");
416→                    content = content.replace(orphanFieldRegex, "");
417→                }
418→            }
419→
420→            documentPackageDetail = {
421→                modified_content: content,
422→            };
423→
424→            await prisma.document_packages_signers_details_values.updateMany({
425→                where: {
426→                    id: parseInt(document_package_signer_detail_value_id),
427→                },
428→                data: documentPackageDetail,
429→            });
430→        }
431→    } catch (err) {
432→       console.log(err)
433→    }
434→}
