534→            company: company,
535→            firstname: user.firstname,
536→            lastname: user.lastname,
537→            passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
538→            date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
539→            time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
540→            _url: url,
541→            company_email: company.email,
542→            documentPackageHeader: header,
543→            sendRequest: true
