 1→"use strict";
 2→
 3→const Queue = require("bull");
 4→const { PrismaClient } = require("@prisma/client");
 5→const axios = require("axios"); 
 6→const db = new PrismaClient();
 7→
 8→const API_URL = process.env.API_URL;
 9→
10→const STATUS = {
11→    PENDING: 0,
12→    SUCCESS: 1, 
13→    FAILED_PERMANENT: 2 
14→};
15→
16→async function validateRequests() {
17→
18→    try {
19→       
20→        const pendingRequests = await db.failed_api_requests.findMany({
21→            where: {
22→                status: STATUS.PENDING,
23→                retry_count: { lt: 3 }, 
24→            },
25→            take: 20 
26→        });
27→
28→        if (pendingRequests.length === 0) {
29→            return;
30→        }
31→
32→        for (const req of pendingRequests) {
33→            try {
34→                const payload = JSON.parse(req.payload);
35→
36→                await axios.post(API_URL, payload, {
37→                    headers: { "Authorization": `Bearer ${process.env.ALI_TOKEN}` },
38→                    timeout: 10000 
39→                });
40→
41→                await db.failed_api_requests.update({
42→                    where: { id: req.id },
43→                    data: { status: STATUS.SUCCESS, updated_at: new Date() }
44→                });
45→
46→                await db.failed_api_requests.delete({
47→                    where: { id: req.id }
48→                });
49→                
50→            } catch (apiError) {
51→                
52→                const nextRetryCount = req.retry_count + 1;
53→                
54→                const newStatus = nextRetryCount >= 3 ? STATUS.FAILED_PERMANENT : STATUS.PENDING;
55→
56→                await db.failed_api_requests.update({
57→                    where: { id: req.id },
58→                    data: {
59→                        retry_count: nextRetryCount,
60→                        status: newStatus,           
61→                        response_body: JSON.stringify(apiError.response?.data || apiError.message),
62→                        response_code: apiError.response?.status || 500,
63→                        updated_at: new Date()    
64→                    }
65→                });
66→            }
67→        }
68→
69→    } catch (error) {
70→        console.error("Error crítico durante la validación de solicitudes:", error);
71→    }
72→}
73→
74→const validateQueue = new Queue("retry-failed-requests", {
75→    redis: { host: "127.0.0.1", port: 6379 },
76→});
77→
78→validateQueue.process(async (job) => {
79→    await validateRequests();
80→});
81→
82→
83→validateQueue.add(
84→    {},
85→    {
86→        repeat: { cron: "*/1 * * * *" }, 
87→    }
88→);
89→
90→module.exports = validateQueue;

