 15→const checkPackages = async () => {
 16→    console.log("Iniciando chequeo de notificaciones preventivas...");
 17→
 18→    const today = moment().startOf('day');
 19→
 20→    const assignments = await prisma.company_packages_assignments.findMany({
 21→        where: {
