 36→                    company_name: true,
 37→                },
 38→            },
 39→        },
 40→    });
 41→
 42→    for (const assignment of assignments) {
 43→        let percentage = 0;
 44→        let message = '';
 45→        let package_type = '';
 46→
 47→        if (assignment.package_id === 1) {
 48→            if (assignment.units) {
 49→                const usedUnits = assignment.units - assignment.remaining_units;
 50→                percentage = (usedUnits / assignment.units) * 100;
 51→
 52→                if (assignment.remaining_units === 1) {
 53→                    message = `Te recordamos que cuentas con pocas unidades en tu paquete. Actualmente solo te queda 1 unidad.`;
 54→                } else {
