 56→                }
 57→                package_type = 'paquete de unidades';
 58→            }
 59→        } else if (assignment.package_id === 2) {
 60→            if (assignment.end_date) {
 61→                const startDate = moment(assignment.start_date).startOf('day');
 62→                const endDate = moment(assignment.end_date).startOf('day');
 63→                const totalDays = endDate.diff(startDate, 'days');
 64→                const elapsedDays = today.diff(startDate, 'days');
 65→                percentage = (elapsedDays / totalDays) * 100;
 66→
 67→                const formattedDate = endDate.add(1, 'days').locale('es').format('LL');
 68→                message = `Te recordamos que tu paquete está próximo a vencerse el ${formattedDate}.`;
 69→                package_type = 'paquete ilimitado';
 70→            }
 71→        }
 72→
 73→        const flooredPercentage = Math.floor(percentage);
 74→
 75→        if (flooredPercentage >= 85 && flooredPercentage < 100) {
 76→            console.log(
 77→                `Enviando notificación de prevencimiento para la empresa: ${assignment.company.company_name}`
 78→            );
 79→            await service.sendNotificacionPrevencimiento(
 80→                assignment.company.company_name,
 81→                message,
 82→                package_type
 83→            );
 84→            await prisma.company_packages_assignments.update({
 85→                where: { id: assignment.id },
 86→                data: { prev_notification_sent: true },
 87→            });
 88→        }
 89→    }
 90→
 91→    console.log("Chequeo de notificaciones preventivas completado.");
 92→};
